import{r as e}from"./authStore-BWdxuuva.js";var t={getBoqs:async t=>(await e.get(`/business/boq`,{params:t})).data.data,getBoq:async t=>(await e.get(`/business/boq/${t}`)).data.data,createBoq:async t=>(await e.post(`/business/boq`,t)).data.data,updateBoq:async(t,n)=>(await e.put(`/business/boq/${t}`,n)).data.data,deleteBoq:async t=>{await e.delete(`/business/boq/${t}`)},updateStatus:async(t,n)=>(await e.patch(`/business/boq/${t}/status`,{status:n})).data.data,duplicateBoq:async t=>(await e.post(`/business/boq/${t}/duplicate`)).data.data,convertToInvoice:async t=>(await e.post(`/business/boq/${t}/convert`)).data.data,generatePdfData:async t=>(await e.get(`/business/boq/${t}/pdf`)).data.data};export{t};